  (() => {
    const telSuc = String($fromAI('telefono_sucursal') || '').replace(/\D/g, '');
    const rawRes = String($fromAI('resumen') || '');
    const ctx = $('Evaluar Estado y Contexto').first().json || {};
    const phonesMap = {
      Centro: '5492944579792',
      Estadio: '5492944638500',
      'Ñireco': '5492944907667',
      Km13: '5492944615570',
      'Bolsón': '5492944631155',
      Dominico: '5491161217529'
    };
    const activePhones = (ctx.sucursalesActivasIntermediario || []).map(k => phonesMap[k]).filter(Boolean);
    const bloqueadaPorIntermediario =
      ctx.intermediarioActivoHoy &&
      activePhones.includes(telSuc) &&
      ctx.estadoCotizacionAnterior !== 'presupuesto_enviado';

    if (bloqueadaPorIntermediario) {
      const sinTelefono = rawRes
        .replace(/Tel[eé]fono[^\n]*/gi, 'Cliente en línea: Esperando presupuesto a través del Bot')
        .replace(/https?:\/\/wa\.me\/[0-9]+/gi, '')
        .replace(/=== NUEVA DERIVACI[OÓ]N ===/gi, '🧾 SOLICITUD DE PRESUPUESTO #' + (ctx.ticketIdSugerido || 'COT'));
      return {
        number: telSuc,
        text: sinTelefono + '\n\n👉 Respondé citando este mensaje con el PDF del presupuesto (o pregunta para el cliente).'
      };
    }
    return {
      number: telSuc,
      text: rawRes
    };
  })()
}}

