const wh = $('Code in JavaScript').first().json;
const sesion = $('Get a document').first().json || {};
const config = $('Get Bot Config').first().json || {};

const botActivoGlobal = config.bot_activo !== false && config.bot_activo !== 'false';
const autoPausaHumana = config.auto_pausa_humana !== false && config.auto_pausa_humana !== 'false';
const delayMs = Number(config.delay_respuesta_ms || 20000);

// Evaluar si el Modo Intermediario de Presupuestos está activo hoy (ej. programado desde 2026-11-10 para Centro)
const modoConfig = String(config.modo_presupuesto_intermediario || 'programado').toLowerCase();
const fechaInicio = String(config.fecha_inicio_intermediario || '2026-11-10').trim();
const hoyArgentina = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Argentina/Buenos_Aires',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date()); // formato YYYY-MM-DD

let intermediarioActivoHoy = false;
if (modoConfig === 'true' || modoConfig === 'activo') {
  intermediarioActivoHoy = true;
} else if (modoConfig === 'programado') {
  intermediarioActivoHoy = Boolean(fechaInicio && hoyArgentina >= fechaInicio);
}

let sucursalesIntermediario = ['Centro'];
try {
  if (config.sucursales_intermediario_json) {
    const parsedSuc = typeof config.sucursales_intermediario_json === 'string'
      ? JSON.parse(config.sucursales_intermediario_json)
      : config.sucursales_intermediario_json;
    if (Array.isArray(parsedSuc)) sucursalesIntermediario = parsedSuc;
  }
} catch (e) {}

const sucursalesActivasIntermediario = intermediarioActivoHoy ? sucursalesIntermediario : [];

let historialPrev = [];
try {
  historialPrev = JSON.parse(sesion.historial_json || '[]');
  if (!Array.isArray(historialPrev)) historialPrev = [];
} catch (e) {
  historialPrev = [];
}

const ultimoBotEnHist = [...historialPrev].reverse().find(m => m && m.rol === 'bot');
const tieneMensajesCliente = historialPrev.some(m => m && m.rol === 'cliente') || Boolean(sesion.resumen_historico && sesion.resumen_historico !== 'Primer contacto. No hay historial previo.');

const esIdDeApi = (wh.messageId || '').startsWith('3EB0') || (wh.messageId || '').startsWith('BAE5');
const msgTrim = (wh.mensajeCliente || '').trim();
const esMismoTextoBot =
  (sesion.ultimo_msg_bot && msgTrim && sesion.ultimo_msg_bot.trim() === msgTrim) ||
  (ultimoBotEnHist && ultimoBotEnHist.texto && msgTrim && ultimoBotEnHist.texto.trim() === msgTrim);

const esEcoPdfPresupuesto =
  wh.fromMe &&
  (
    msgTrim.includes('Presupuesto adjunto — Check-Oil') ||
    (sesion.fecha_respuesta_cotizacion && Math.abs(Date.now() - new Date(sesion.fecha_respuesta_cotizacion).getTime()) < 90000)
  );

const esEcoBot = wh.fromMe && (esIdDeApi || esMismoTextoBot || esEcoPdfPresupuesto);
const esIntervencionHumana = wh.fromMe && !esEcoBot;

let botPausado = sesion.bot_pausado === true || sesion.bot_pausado === 'true';
let motivoPausa = sesion.motivo_pausa || '';
let pausadoEn = sesion.pausado_en || '';

if (botPausado && !wh.fromMe && pausadoEn) {
  const horasPausa = (Date.now() - new Date(pausadoEn).getTime()) / (1000 * 60 * 60);
  if (horasPausa > 6) {
    botPausado = false;
    motivoPausa = '';
    pausadoEn = '';
  }
}

if (esIntervencionHumana && autoPausaHumana && tieneMensajesCliente) {
  botPausado = true;
  motivoPausa = 'Operador humano intervino desde WhatsApp';
  pausadoEn = new Date().toISOString();
}

let reglasLista = [];
try {
  if (config.reglas_aprendidas_json) {
    const parsed = JSON.parse(config.reglas_aprendidas_json);
    if (Array.isArray(parsed)) {
      reglasLista = parsed
        .filter(r => r && r.activa !== false)
        .map(r => `- Cuando consulten sobre "${r.pregunta || r.tema}": ${r.respuesta}`);
    }
  }
} catch (e) {}

if (config.prompt_extra && String(config.prompt_extra).trim()) {
  reglasLista.unshift(`- DIRECTIVA GENERAL: ${String(config.prompt_extra).trim()}`);
}

const estadoCotizacionActual = sesion.estado_cotizacion || '';
const ticketIdActual = sesion.ticket_id || '';
const sucursalCotizacionActual = sesion.sucursal_cotizacion || sesion.sucursal_elegida || '';
const ultimaPreguntaSucursal = sesion.ultima_pregunta_sucursal || '';

let cotizacionActualObj = null;
try {
  if (sesion.cotizacion_actual_json) {
    cotizacionActualObj = typeof sesion.cotizacion_actual_json === 'string'
      ? JSON.parse(sesion.cotizacion_actual_json)
      : sesion.cotizacion_actual_json;
  }
} catch (e) {}

// Construir contexto dinámico de intermediación de presupuestos para el Agente IA
let directivaPresupuestoTexto = '';
if (sucursalesActivasIntermediario.length > 0) {
  const listaSucStr = sucursalesActivasIntermediario.join(', ');
  directivaPresupuestoTexto =
    `MODO INTERMEDIARIO DE PRESUPUESTOS ACTIVO PARA SUCURSALES: [${listaSucStr}].\n` +
    `- Para cualquier sucursal dentro de [${listaSucStr}], PROHIBIDO derivar o pasar el teléfono del cliente antes de que el presupuesto sea confirmado.\n` +
    `- Cuando el cliente pida precio/presupuesto/service en [${listaSucStr}] y ya tengas Marca, Modelo, Año y Motor, usa la herramienta "Gestionar_Presupuesto_Sucursal" con tipo_accion="solicitar_presupuesto" (NUNCA uses Enviar_Derivacion_Sucursal todavía). Avísale al cliente que ya estás consultando el presupuesto con la sucursal y que le responderás por este mismo chat en unos minutos.\n`;

  if (estadoCotizacionActual === 'esperando_respuesta_cliente') {
    directivaPresupuestoTexto +=
      `\nATENCIÓN PRIORITARIA — TICKET ABIERTO #${ticketIdActual} (${sucursalCotizacionActual}):\n` +
      `La sucursal acaba de preguntar: "${ultimaPreguntaSucursal}". El cliente está respondiendo a esa consulta. Usa INMEDIATAMENTE la herramienta "Gestionar_Presupuesto_Sucursal" con tipo_accion="reenviar_respuesta_cliente" pasando la respuesta del cliente a la sucursal, y dile al cliente: "¡Gracias! Ya le pasé el dato a la sucursal para completar tu presupuesto."\n`;
  } else if (estadoCotizacionActual === 'presupuesto_enviado') {
    const resumenCot = cotizacionActualObj
      ? `Total cotizado: $${cotizacionActualObj.total_cotizado || '-'} (${cotizacionActualObj.resumen_items || ''})`
      : 'Presupuesto ya entregado al cliente';
    directivaPresupuestoTexto +=
      `\nATENCIÓN PRIORITARIA — PRESUPUESTO YA ENVIADO AL CLIENTE (#${ticketIdActual} • ${resumenCot}):\n` +
      `- Si el cliente ACEPTA, CONFIRMA el trabajo o pide TURNO/RESERVA ("dale", "lo hago", "quiero turno", "confirmo", "¿puedo ir hoy?"): AHORA SÍ ejecuta "Enviar_Derivacion_Sucursal" pasando el teléfono del cliente (${wh.telefonoCliente}) y link https://wa.me/${wh.telefonoCliente} indicando "✅ PRESUPUESTO CONFIRMADO #${ticketIdActual}", y despídete confirmando que la sucursal se comunica para coordinar el turno.\n` +
      `- Si el cliente hace una OTRA CONSULTA o pide recotizar con otra marca/aceite/filtro: usa "Gestionar_Presupuesto_Sucursal" con tipo_accion="repregunta_cliente" para trasladar esa consulta a la sucursal.\n`;
  } else if (estadoCotizacionActual === 'esperando_sucursal') {
    directivaPresupuestoTexto +=
      `\nNOTA: El cliente ya tiene el pedido #${ticketIdActual} esperando respuesta de ${sucursalCotizacionActual}. Si pregunta si hay novedades, infórmale amablemente que la sucursal está armando su cotización y apenas respondan se la envías por acá (si agrega algún dato extra del auto, pásalo con Gestionar_Presupuesto_Sucursal tipo_accion="reenviar_respuesta_cliente").\n`;
  }
} else {
  directivaPresupuestoTexto = 'Modo Intermediario inactivo hoy: todas las sucursales operan con derivación directa habitual usando Enviar_Derivacion_Sucursal.';
}

const reglasAprendidasTexto = reglasLista.length > 0
  ? reglasLista.join('\n')
  : 'Sin directivas adicionales.';

// Si el cliente había dicho "ok/gracias" pero tenía un presupuesto enviado, "dale" es confirmación, no cortesía vacía
const esConfirmacionCorta =
  estadoCotizacionActual === 'presupuesto_enviado' &&
  ['dale', 'ok', 'okay', 'listo', 'si', 'sí', 'confirmo', 'de una'].includes(
    (wh.mensajeCliente || '').toLowerCase().replace(/[\!\?\.\,\s]+/g, ' ').trim()
  );

const tieneTexto = Boolean(wh.mensajeCliente && wh.mensajeCliente.trim().length > 0);

const debeResponderBot =
  !wh.esSucursalOGrupo &&
  !wh.esStickerOReaccion &&
  (!wh.esCortesia || esConfirmacionCorta) &&
  !wh.fromMe &&
  botActivoGlobal &&
  !botPausado &&
  tieneTexto;

const debeObservar =
  !wh.esSucursalOGrupo &&
  !wh.esStickerOReaccion &&
  !esEcoBot &&
  tieneTexto &&
  (!wh.fromMe || tieneMensajesCliente);

// Generar nuevo ticket_id sugerido si aún no tiene uno activo
const ticketIdSugerido = ticketIdActual && estadoCotizacionActual && estadoCotizacionActual !== 'confirmado'
  ? ticketIdActual
  : `COT-${String(Date.now()).slice(-4)}`;

return {
  json: {
    remoteJid: wh.remoteJid,
    telefonoCliente: wh.telefonoCliente,
    mensajeCliente: wh.mensajeCliente,
    fromMe: wh.fromMe,
    pushName: wh.pushName,
    tipoMensaje: wh.tipoMensaje,
    esIntervencionHumana,
    botPausado,
    motivoPausa,
    pausadoEn,
    delayMs,
    intermediarioActivoHoy,
    sucursalesActivasIntermediario,
    directivaPresupuestoTexto,
    ticketIdSugerido,
    estadoCotizacionAnterior: estadoCotizacionActual,
    sucursalCotizacionAnterior: sucursalCotizacionActual,
    ultimaPreguntaSucursal,
    reglasAprendidasTexto,
    debeResponderBot,
    debeObservar,
    resumenAnterior: sesion.resumen_historico || '',
    historialJsonAnterior: sesion.historial_json || '[]',
    totalMensajesAnterior: Number(sesion.total_mensajes || 0)
  },
  pairedItem: { item: 0 }
};

const ctx = $('Evaluar Estado y Contexto').first().json;

return {
  json: {
    ...ctx,
    output: ctx.esIntervencionHumana
      ? `[OPERADOR HUMANO RESPONDIÓ]: ${ctx.mensajeCliente}`
      : '[BOT EN PAUSA - MODO OBSERVACIÓN]',
    enviarWhatsApp: false,
    modoInteraccion: ctx.esIntervencionHumana ? 'intervencion_humana' : 'bot_pausado_observando'
  },
  pairedItem: { item: 0 }
};

const ctx = $('Evaluar Estado y Contexto').first().json;
const rawOutput = ($input.item.json.output || '').trim();

const noResponder =
  !rawOutput ||
  rawOutput.includes('[NO_RESPONDER]') ||
  rawOutput === 'NO_RESPONDER';

const textoLimpio = noResponder ? '' : rawOutput.replace('[NO_RESPONDER]', '').trim();

return {
  json: {
    ...ctx,
    output: textoLimpio,
    enviarWhatsApp: Boolean(textoLimpio.length > 0),
    modoInteraccion: 'bot_activo'
  },
  pairedItem: { item: 0 }
};

const rawModel = $input.item.json;
let ctx = {};
try {
  ctx = $('Preparar Envio y Analisis').first().json;
} catch (e) {
  try {
    ctx = $('Modo Observador Pausa').first().json;
  } catch (e2) {
    ctx = $('Evaluar Estado y Contexto').first().json;
  }
}

const sesionPrev = $('Get a document').first().json || {};

let textoIA = '';
if (rawModel.output && Array.isArray(rawModel.output) && rawModel.output[0]?.content?.[0]?.text) {
  textoIA = rawModel.output[0].content[0].text;
} else if (rawModel.message && rawModel.message.content) {
  textoIA = rawModel.message.content;
} else if (typeof rawModel.text === 'string') {
  textoIA = rawModel.text;
}

let parsed = {};
try {
  const clean = textoIA.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    resumen_historico: textoIA || ctx.resumenAnterior || 'Sin resumen',
    resumen_charla: textoIA || 'Interacción registrada',
    estado_charla: ctx.botPausado ? 'atendida_humano' : 'en_curso'
  };
}

let historial = [];
try {
  historial = JSON.parse(ctx.historialJsonAnterior || '[]');
  if (!Array.isArray(historial)) historial = [];
} catch (e) {
  historial = [];
}

const ahora = new Date().toISOString();
if (ctx.esIntervencionHumana) {
  historial.push({
    rol: 'operador',
    texto: ctx.mensajeCliente,
    fecha: ahora
  });
} else {
  historial.push({
    rol: 'cliente',
    nombre: ctx.pushName || 'Cliente',
    texto: ctx.mensajeCliente,
    fecha: ahora
  });
  if (ctx.enviarWhatsApp && ctx.output) {
    historial.push({
      rol: 'bot',
      texto: ctx.output,
      fecha: ahora
    });
  }
}
if (historial.length > 45) {
  historial = historial.slice(historial.length - 45);
}

