// Helper: calcula minutos hábiles dentro del horario comercial en Argentina
function calcularMinutosHabiles(startIso, endIso, horarioJsonStr) {
  const start = new Date(startIso);
  const end = new Date(endIso);
  if (isNaN(start.getTime()) || isNaN(end.getTime()) || end <= start) return 0;

  let schedule = {
    lun_vie_apertura: '08:30',
    lun_vie_cierre: '20:00',
    sab_apertura: '09:00',
    sab_cierre: '13:30',
    dom_abierto: false
  };
  try {
    if (horarioJsonStr) {
      const p = typeof horarioJsonStr === 'string' ? JSON.parse(horarioJsonStr) : horarioJsonStr;
      schedule = { ...schedule, ...p };
    }
  } catch (e) {}

  const toMin = (hhmm) => {
    const [h, m] = String(hhmm || '08:30').split(':').map(Number);
    return (h || 0) * 60 + (m || 0);
  };
  const lvOpen = toMin(schedule.lun_vie_apertura);
  const lvClose = toMin(schedule.lun_vie_cierre);
  const sabOpen = toMin(schedule.sab_apertura);
  const sabClose = toMin(schedule.sab_cierre);

  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Argentina/Buenos_Aires',
    weekday: 'short',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });

  let count = 0;
  let cursor = Math.floor(start.getTime() / 60000) * 60000;
  const endMs = Math.floor(end.getTime() / 60000) * 60000;
  // Tope de seguridad 10080 iteraciones (7 días)
  const maxStepEnd = Math.min(endMs, cursor + 10080 * 60000);

  while (cursor < maxStepEnd) {
    const parts = fmt.formatToParts(new Date(cursor));
    const wk = (parts.find(p => p.type === 'weekday') || {}).value || '';
    const hh = Number((parts.find(p => p.type === 'hour') || {}).value || 0) % 24;
    const mm = Number((parts.find(p => p.type === 'minute') || {}).value || 0);
    const curMin = hh * 60 + mm;

    if (wk === 'Sun') {
      if (schedule.dom_abierto && curMin >= sabOpen && curMin < sabClose) count++;
    } else if (wk === 'Sat') {
      if (curMin >= sabOpen && curMin < sabClose) count++;
    } else {
      if (curMin >= lvOpen && curMin < lvClose) count++;
    }
    cursor += 60000;
  }
  return count;
}

