let estadoCotizacionNuevo = targetSession.estado_cotizacion || 'esperando_sucursal';
let estadoCharlaNuevo = targetSession.estado_charla || 'en_curso';
let textoParaCliente = '';
let enviarPdfAlCliente = false;
let cotizacionActualJson = targetSession.cotizacion_actual_json || '';
let cotizacionesHistorialJson = targetSession.cotizaciones_historial_json || '[]';
let ultimaPreguntaSucursal = targetSession.ultima_pregunta_sucursal || '';
let fechaRespuestaCotizacion = targetSession.fecha_respuesta_cotizacion || '';

if (parsed.tipo_respuesta_sucursal === 'pregunta_al_cliente') {
  estadoCotizacionNuevo = 'esperando_respuesta_cliente';
  estadoCharlaNuevo = 'esperando_respuesta_cliente';
  ultimaPreguntaSucursal = wh.mensajeCliente || parsed.pregunta_para_cliente || '';
  textoParaCliente = parsed.pregunta_para_cliente ||
    `Te hago una consulta rápida que me piden desde ${wh.sucursalOrigenNombre} para cotizar exacto tu vehículo: ${wh.mensajeCliente}`;

  historial.push({
    rol: 'sucursal',
    nombre: wh.sucursalOrigenNombre,
    texto: `[CONSULTA DE SUCURSAL #${targetSession.ticket_id}]: ${wh.mensajeCliente}`,
    fecha: ahora
  });
  historial.push({
    rol: 'bot',
    texto: textoParaCliente,
    fecha: ahora
  });
} else if (parsed.tipo_respuesta_sucursal === 'presupuesto') {
  estadoCotizacionNuevo = 'presupuesto_enviado';
  estadoCharlaNuevo = 'presupuesto_enviado';
  fechaRespuestaCotizacion = ahora;

  const aud = parsed.analisis_auditoria || {};
  const formatoOrigen = wh.tipoMensaje === 'documento' ? 'pdf' : (wh.tipoMensaje === 'imagen' ? 'imagen' : 'texto');

  const registroCotizacion = {
    ticket_id: targetSession.ticket_id || `COT-${String(Date.now()).slice(-4)}`,
    cliente_jid: targetSession.documentId,
    cliente_nombre: targetSession.cliente_nombre || 'Cliente',
    cliente_telefono: targetSession.cliente_telefono || targetSession.documentId.replace('@s.whatsapp.net', ''),
    sucursal: wh.sucursalOrigenKey,
    sucursal_nombre: wh.sucursalOrigenNombre,
    vehiculo: targetSession.vehiculo || aud.vehiculo_detectado_en_pdf || 'No especificado',
    fecha_pedido: inicioTotalIso,
    fecha_respuesta: ahora,
    demora_total_min: demoraCorridaMin,
    demora_habil_min: demoraHabilTotalMin,
    demora_neta_sucursal_min: demoraNetaSucursalMin,
    formato_origen: formatoOrigen,
    archivo_nombre: prep.mediaName || '',
    moneda: aud.moneda || 'ARS',
    total_cotizado: Number(aud.total_cotizado || 0),
    total_con_descuento: Number(aud.total_con_descuento || 0),
    descuento_porcentaje: Number(aud.descuento_porcentaje || 0),
    aceite: aud.aceite || null,
    filtros: Array.isArray(aud.filtros) ? aud.filtros : [],
    otros_items: Array.isArray(aud.otros_items) ? aud.otros_items : [],
    resumen_items: aud.resumen_items_corto || '',
    observaciones_calidad: aud.observaciones_calidad || '',
    texto_original_sucursal: wh.mensajeCliente || '',
    estado: 'presupuesto_enviado'
  };

  cotizacionActualJson = JSON.stringify(registroCotizacion);
  try {
    const prevList = JSON.parse(cotizacionesHistorialJson || '[]');
    const arr = Array.isArray(prevList) ? prevList : [];
    const existingIdx = arr.findIndex(item => item && item.ticket_id === registroCotizacion.ticket_id);
    if (existingIdx >= 0) arr[existingIdx] = registroCotizacion;
    else arr.unshift(registroCotizacion);
    cotizacionesHistorialJson = JSON.stringify(arr.slice(0, 20));
  } catch (e) {
    cotizacionesHistorialJson = JSON.stringify([registroCotizacion]);
  }

  textoParaCliente = parsed.resumen_para_cliente ||
    `¡Ya tenemos el presupuesto de ${wh.sucursalOrigenNombre} para tu ${registroCotizacion.vehiculo}!\n\n` +
    (registroCotizacion.resumen_items ? `• Detalle: ${registroCotizacion.resumen_items}\n` : '') +
    (registroCotizacion.total_cotizado ? `• Total: $${registroCotizacion.total_cotizado.toLocaleString('es-AR')}\n\n` : '\n') +
    `¿Querés que confirmemos este presupuesto para coordinar tu turno?`;

  enviarPdfAlCliente = Boolean(prep.mediaBase64 && (wh.tipoMensaje === 'documento' || wh.tipoMensaje === 'imagen'));

  historial.push({
    rol: 'sucursal',
    nombre: wh.sucursalOrigenNombre,
    texto: `[PRESUPUESTO RECIBIDO #${registroCotizacion.ticket_id} • Demora hábil: ${demoraNetaSucursalMin} min • Formato: ${formatoOrigen.toUpperCase()}] ${registroCotizacion.resumen_items || wh.mensajeCliente} ${registroCotizacion.total_cotizado ? '($' + registroCotizacion.total_cotizado.toLocaleString('es-AR') + ')' : ''}`,
    fecha: ahora
  });
  historial.push({
    rol: 'bot',
    texto: textoParaCliente + (enviarPdfAlCliente ? `\n📎 [Archivo reenviado: ${prep.mediaName}]` : ''),
    fecha: ahora
  });
}

if (historial.length > 45) {
  historial = historial.slice(historial.length - 45);
}

return [
  {
    json: {
      guardarSesion: true,
      enviarPdfAlCliente,
      enviarTextoAlCliente: Boolean(textoParaCliente),
      enviarAclaracionASucursal: false,
      clienteJid: targetSession.documentId,
      textoParaCliente,
      mediaBase64: prep.mediaBase64 || '',
      mediaMime: prep.mediaMime || 'application/pdf',
      mediaTypeEvolution: wh.tipoMensaje === 'imagen' ? 'image' : 'document',
      mediaName: prep.mediaName || 'Presupuesto_CheckOil.pdf',
      // Campos de Firestore sesiones_clientes
      documentId: targetSession.documentId,
      resumen_historico: targetSession.resumen_historico || '',
      resumen_charla: parsed.tipo_respuesta_sucursal === 'presupuesto'
        ? `Presupuesto #${targetSession.ticket_id} enviado al cliente (${demoraNetaSucursalMin} min hábiles). Esperando confirmación.`
        : `Sucursal consultó al cliente (#${targetSession.ticket_id}): ${ultimaPreguntaSucursal}`,
      estado_charla: estadoCharlaNuevo,
      bot_pausado: String(targetSession.bot_pausado || 'false'),
      motivo_pausa: targetSession.motivo_pausa || '',
      pausado_en: targetSession.pausado_en || '',
      vehiculo: targetSession.vehiculo || 'No especificado',
      sucursal_elegida: targetSession.sucursal_elegida || wh.sucursalOrigenKey,
      cliente_nombre: targetSession.cliente_nombre || 'Cliente',
      cliente_telefono: targetSession.cliente_telefono || targetSession.documentId.replace('@s.whatsapp.net', ''),
      fuera_de_contexto: targetSession.fuera_de_contexto || 'no',
      incompleta_motivo: targetSession.incompleta_motivo || '',
      pregunta_detectada: targetSession.pregunta_detectada || '',
      aprendizaje_sugerido: targetSession.aprendizaje_sugerido || '',
      estado_aprendizaje: targetSession.estado_aprendizaje || '',
      historial_json: JSON.stringify(historial),
      total_mensajes: String(historial.length),
      ultima_interaccion: ahora,
      ultimo_msg_bot: textoParaCliente,
      ticket_id: targetSession.ticket_id || '',
      estado_cotizacion: estadoCotizacionNuevo,
      sucursal_cotizacion: wh.sucursalOrigenKey,
      fecha_pedido_cotizacion: inicioTotalIso,
      ultimo_pedido_sucursal_en: targetSession.ultimo_pedido_sucursal_en || inicioTotalIso,
      fecha_respuesta_cotizacion: fechaRespuestaCotizacion,
      fecha_confirmacion: targetSession.fecha_confirmacion || '',
      demora_total_min: String(demoraCorridaMin),
      demora_habil_min: String(demoraHabilTotalMin),
      demora_neta_sucursal_min: String(demoraNetaSucursalMin),
      segundos_acumulados_sucursal: String(segAcumTotal),
      recordatorio_enviado: String(targetSession.recordatorio_enviado || 'false'),
      ultima_pregunta_sucursal: ultimaPreguntaSucursal,
      cotizacion_actual_json: cotizacionActualJson,
      cotizaciones_historial_json: cotizacionesHistorialJson
    }
  }
];

